using Og.Core.Runtime;

namespace Og.Core.Tests;

/// <summary>
/// Equip has always been able to swap one weapon or armor for another. Until
/// now there was no way back to bare hands: no verb moved a worn item into the
/// pack without something else to replace it. Unequip (and its synonyms) fixes
/// that, symmetrically with equip's own swap-into-inventory branch.
/// </summary>
public class UnequipTests
{
    [Fact]
    public void UnequippingAWeaponMovesItToInventory()
    {
        var (engine, events) = WorldFixture.NewEngine();
        var (alice, output) = WorldFixture.Join(engine, "Alice");

        Assert.Equal("dagger", alice.Character.Weapon?.Name);

        engine.HandleInput(alice, "unequip dagger");

        Assert.Null(alice.Character.Weapon);
        Assert.Contains(alice.Character.Inventory, item => item.Name == "dagger");
        Assert.Contains("You unequip the dagger.", output.Text);
        Assert.Contains(events.Events, e => e.Type == EventType.ItemUnequipped && e.Payload["item"] == "dagger");
    }

    [Fact]
    public void ADroppedWeaponCanThenBeDroppedForReal()
    {
        // This is the actual complaint that motivated the fix: drop only ever
        // searched Inventory, so an equipped item couldn't be laid down at all,
        // not even in two steps. Now it can.
        var (engine, _) = WorldFixture.NewEngine();
        var (alice, output) = WorldFixture.Join(engine, "Alice");

        engine.HandleInput(alice, "unequip dagger");
        engine.HandleInput(alice, "drop dagger");

        Assert.Null(alice.Character.Weapon);
        Assert.DoesNotContain(alice.Character.Inventory, item => item.Name == "dagger");
        Assert.Contains("You drop the dagger.", output.Text);
    }

    [Fact]
    public void SynonymsWorkTheSameWay()
    {
        var (engine, _) = WorldFixture.NewEngine();
        var (alice, output) = WorldFixture.Join(engine, "Alice");

        engine.HandleInput(alice, "remove dagger");

        Assert.Null(alice.Character.Weapon);
        Assert.Contains("You unequip the dagger.", output.Text);
    }

    [Fact]
    public void UnequippingSomethingNotEquippedIsFutileNotBroken()
    {
        var (engine, _) = WorldFixture.NewEngine();
        var (alice, output) = WorldFixture.Join(engine, "Alice");
        alice.Character.Inventory.Add(engine.World.CreateItem("shiny spoon")!);

        engine.HandleInput(alice, "unequip shiny spoon");

        Assert.Contains("isn't equipped", output.Text);
        Assert.Contains(alice.Character.Inventory, item => item.Name == "shiny spoon");
    }

    [Fact]
    public void UnequippingSomethingYouDoNotHaveIsFutile()
    {
        var (engine, _) = WorldFixture.NewEngine();
        var (alice, output) = WorldFixture.Join(engine, "Alice");

        engine.HandleInput(alice, "unequip broadsword");

        Assert.Contains("You aren't carrying anything called \"broadsword\"", output.Text);
    }
}

